def solve(facts):
    alphabet = facts['alphabet']
    n = facts['length']
    m = facts['modulus']
    residue = facts['residue']
    low, high = facts['sum_min'], facts['sum_max']
    target, required = facts['target_digit'], facts['target_count']
    states = {(None, 0, 0, 0): 1}
    for position in range(n):
        following = {}
        for (previous, remainder, total, copies), multiplicity in states.items():
            for digit in alphabet:
                if digit == previous:
                    continue
                new_total = total + digit
                new_copies = copies + int(digit == target)
                if new_total > high or new_copies > required:
                    continue
                if new_copies + n - position - 1 < required:
                    continue
                key = (digit, (remainder * 10 + digit) % m, new_total, new_copies)
                following[key] = following.get(key, 0) + multiplicity
        states = following
    count = 0
    digit_sum_total = 0
    for (previous, remainder, total, copies), multiplicity in states.items():
        if remainder == residue and low <= total <= high and copies == required:
            count += multiplicity
            digit_sum_total += multiplicity * total
    return {'count': count, 'digit_sum_total': digit_sum_total}

def check(answer, facts):
    alphabet = facts['alphabet']
    n, m = facts['length'], facts['modulus']
    residue = facts['residue']
    low, high = facts['sum_min'], facts['sum_max']
    target, required = facts['target_digit'], facts['target_count']
    if not 0 <= residue < m:
        return answer == {'count': 0, 'digit_sum_total': 0}

    def enumerate_half(size, use_first):
        distribution = {}
        stack = [(0, 0, 0, 0, None, None)]
        while stack:
            position, remainder, total, copies, first, last = stack.pop()
            if position == size:
                boundary = first if use_first else last
                key = (remainder, total, copies, boundary)
                distribution[key] = distribution.get(key, 0) + 1
                continue
            for digit in alphabet:
                if digit != last:
                    stack.append((position + 1, (remainder * 10 + digit) % m,
                                  total + digit, copies + int(digit == target),
                                  digit if position == 0 else first, digit))
        return distribution

    left_size = n // 2
    right_size = n - left_size
    left = enumerate_half(left_size, False)
    right = enumerate_half(right_size, True)
    groups = {}
    for (remainder, total, copies, boundary), multiplicity in right.items():
        key = (remainder, copies, boundary)
        if key not in groups:
            groups[key] = {}
        groups[key][total] = groups[key].get(total, 0) + multiplicity
    indexed = {}
    for key, totals in groups.items():
        sums = sorted(totals)
        counts = [0]
        weighted = [0]
        for total in sums:
            counts.append(counts[-1] + totals[total])
            weighted.append(weighted[-1] + total * totals[total])
        indexed[key] = (sums, counts, weighted)
    factor = pow(10, right_size, m)
    count = 0
    digit_sum_total = 0
    boundaries = alphabet if right_size else [None]
    for (remainder, total, copies, last), multiplicity in left.items():
        wanted = (residue - remainder * factor) % m
        for first in boundaries:
            if left_size and right_size and last == first:
                continue
            key = (wanted, required - copies, first)
            if key not in indexed:
                continue
            sums, counts, weighted = indexed[key]
            start = bisect_left(sums, low - total)
            end = bisect_right(sums, high - total)
            if end <= start:
                continue
            matches = counts[end] - counts[start]
            count += multiplicity * matches
            digit_sum_total += multiplicity * (total * matches + weighted[end] - weighted[start])
    return answer == {'count': count, 'digit_sum_total': digit_sum_total}
